import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.Dh1jimFm.js";const c=JSON.parse('{"title":"memoQ Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"cat-tools/memoq.md","filePath":"cat-tools/memoq.md"}'),l={name:"cat-tools/memoq.md"};function i(n,e,s,m,p,d){return a(),o("div",null,e[0]||(e[0]=[r(`<h1 id="memoq-workflow" tabindex="-1">memoQ Workflow <a class="header-anchor" href="#memoq-workflow" aria-label="Permalink to &quot;memoQ Workflow&quot;">​</a></h1><p>This guide covers working with memoQ bilingual files in Supervertaler.</p><h2 id="export-from-memoq" tabindex="-1">Export from memoQ <a class="header-anchor" href="#export-from-memoq" aria-label="Permalink to &quot;Export from memoQ&quot;">​</a></h2><h3 id="bilingual-docx-recommended" tabindex="-1">Bilingual DOCX (Recommended) <a class="header-anchor" href="#bilingual-docx-recommended" aria-label="Permalink to &quot;Bilingual DOCX (Recommended)&quot;">​</a></h3><ol><li>In memoQ, open your project</li><li>Go to <strong>Documents</strong> view</li><li>Right-click your document → <strong>Export Bilingual...</strong></li><li>Choose <strong>Bilingual DOC/RTF/DOCX</strong></li><li>Select <strong>Table format</strong> (two columns)</li><li>Export the file</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The table format with source and target columns works best with Supervertaler.</p></div><h3 id="xliff-export" tabindex="-1">XLIFF Export <a class="header-anchor" href="#xliff-export" aria-label="Permalink to &quot;XLIFF Export&quot;">​</a></h3><ol><li>In memoQ, go to <strong>Documents</strong> view</li><li>Right-click → <strong>Export Bilingual...</strong></li><li>Choose <strong>memoQ XLIFF bilingual</strong></li><li>Save the <code>.mqxliff</code> file</li></ol><h2 id="import-to-supervertaler" tabindex="-1">Import to Supervertaler <a class="header-anchor" href="#import-to-supervertaler" aria-label="Permalink to &quot;Import to Supervertaler&quot;">​</a></h2><ol><li>Go to <strong>File → Import → memoQ Bilingual DOCX...</strong><ul><li>Or <strong>File → Import → memoQ XLIFF...</strong></li></ul></li><li>Select your exported file</li><li>The segments appear in the translation grid</li></ol><h3 id="what-gets-imported" tabindex="-1">What Gets Imported <a class="header-anchor" href="#what-gets-imported" aria-label="Permalink to &quot;What Gets Imported&quot;">​</a></h3><ul><li>✅ Source text</li><li>✅ Target text (if any)</li><li>✅ Inline formatting tags (<code>{1}</code>, <code>[2}</code>, etc.)</li><li>✅ Segment status</li></ul><h3 id="memoq-tag-handling" tabindex="-1">memoQ Tag Handling <a class="header-anchor" href="#memoq-tag-handling" aria-label="Permalink to &quot;memoQ Tag Handling&quot;">​</a></h3><p>memoQ uses special tag formats:</p><table tabindex="0"><thead><tr><th>Tag Style</th><th>Example</th><th>Purpose</th></tr></thead><tbody><tr><td>Curly</td><td><code>{1}</code></td><td>Inline tag</td></tr><tr><td>Mixed</td><td><code>[2}</code> or <code>{3]</code></td><td>Start/end tags</td></tr><tr><td>Named</td><td><code>{MQ}</code>, <code>{tspan}</code></td><td>Formatting tags</td></tr></tbody></table><p>These tags are highlighted in dark red in the grid (matching memoQ&#39;s color).</p><h2 id="translate-in-supervertaler" tabindex="-1">Translate in Supervertaler <a class="header-anchor" href="#translate-in-supervertaler" aria-label="Permalink to &quot;Translate in Supervertaler&quot;">​</a></h2><ol><li>Navigate through segments</li><li>Use AI translation (<code>Ctrl+T</code>) or translate manually</li><li>Confirm each segment (<code>Ctrl+Enter</code>)</li><li>Save your project regularly (<code>Ctrl+S</code>)</li></ol><h3 id="tips-for-memoq-projects" tabindex="-1">Tips for memoQ Projects <a class="header-anchor" href="#tips-for-memoq-projects" aria-label="Permalink to &quot;Tips for memoQ Projects&quot;">​</a></h3><ul><li><strong>Preserve tags</strong>: Keep all <code>{1}</code>, <code>[2}</code> tags in your translation</li><li><strong>Use Superlookup</strong>: Press <code>Ctrl+K</code> for TM and glossary searches</li><li><strong>Batch translate</strong>: Select multiple segments and press <code>Ctrl+Shift+T</code></li></ul><h2 id="export-from-supervertaler" tabindex="-1">Export from Supervertaler <a class="header-anchor" href="#export-from-supervertaler" aria-label="Permalink to &quot;Export from Supervertaler&quot;">​</a></h2><ol><li>Go to <strong>File → Export → memoQ Bilingual DOCX...</strong></li><li>Choose a filename</li><li>The bilingual table is recreated with your translations</li></ol><h2 id="import-back-to-memoq" tabindex="-1">Import Back to memoQ <a class="header-anchor" href="#import-back-to-memoq" aria-label="Permalink to &quot;Import Back to memoQ&quot;">​</a></h2><ol><li>In memoQ, go to <strong>Documents</strong> view</li><li>Right-click your original document</li><li>Select <strong>Import/Update Translation...</strong></li><li>Choose <strong>From bilingual DOC/RTF/DOCX file</strong></li><li>Select the file exported from Supervertaler</li><li>Click <strong>Import</strong></li></ol><h3 id="verify-the-import" tabindex="-1">Verify the Import <a class="header-anchor" href="#verify-the-import" aria-label="Permalink to &quot;Verify the Import&quot;">​</a></h3><ul><li>Check that translations appear in memoQ</li><li>Confirm status shows as &quot;Translated&quot; or &quot;Edited&quot;</li><li>Run memoQ&#39;s QA to check for issues</li></ul><h2 id="complete-workflow" tabindex="-1">Complete Workflow <a class="header-anchor" href="#complete-workflow" aria-label="Permalink to &quot;Complete Workflow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>memoQ: Export Bilingual DOCX</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>Supervertaler: Import memoQ Bilingual</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>Supervertaler: Translate (AI + manual)</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>Supervertaler: Export memoQ Bilingual</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>memoQ: Import/Update Translation</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>memoQ: QA + Delivery</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="tags-appear-as-plain-text" tabindex="-1">Tags appear as plain text <a class="header-anchor" href="#tags-appear-as-plain-text" aria-label="Permalink to &quot;Tags appear as plain text&quot;">​</a></h3><p>Make sure you exported as <strong>Bilingual DOCX</strong> (not &quot;Export without tags&quot;).</p><h3 id="formatting-lost-on-re-import" tabindex="-1">Formatting lost on re-import <a class="header-anchor" href="#formatting-lost-on-re-import" aria-label="Permalink to &quot;Formatting lost on re-import&quot;">​</a></h3><p>This can happen if:</p><ul><li>Tags were deleted or modified during translation</li><li>The bilingual table structure was changed</li></ul><p><strong>Solution</strong>: Always keep tags exactly as they appear.</p><h3 id="status-not-updating-in-memoq" tabindex="-1">Status not updating in memoQ <a class="header-anchor" href="#status-not-updating-in-memoq" aria-label="Permalink to &quot;Status not updating in memoQ&quot;">​</a></h3><p>memoQ&#39;s import may not change segment status. You can:</p><ul><li>Use memoQ&#39;s filtering to find imported segments</li><li>Manually confirm segments in memoQ if needed</li></ul><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./overview.html">CAT Tool Overview</a></li><li><a href="./../tools/autofingers.html">AutoFingers (memoQ Automation)</a></li></ul>`,41)]))}const u=t(l,[["render",i]]);export{c as __pageData,u as default};
